with open('region.fasta') as f:
    lines=f.read().splitlines()
seq=''.join(lines[1:]).upper()
n=len(seq)
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
tab={'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L','ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V','TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P','ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A','TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E','TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R','AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
def tr(s): return ''.join(tab.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def orfmask(s,strand):
    res=[]
    for fr in range(3):
        t=tr(s[fr:])
        i=0
        while i<len(t):
            if t[i]=='M':
                j=i
                while j<len(t) and t[j]!='*': j+=1
                if j-i>=60:
                    if strand=='+':
                        ns=fr+i*3; ne=fr+j*3+2
                        coords=(ns+1,ne+1)  # 1-based inclusive over start..stop
                    else:
                        # position in rc coords -> convert
                        ns=fr+i*3; ne=fr+j*3+2
                        # rc index k corresponds to original n-1-k
                        coords=(n-ne, n-ns)
                    res.append((strand,fr+1,j-i,coords,t[i:j]))
            i+=1
    return res

allf=sorted(orfmask(seq,'+')+orfmask(rc(seq),'-'), key=lambda x:-x[2])
print("ORFs >=60 aa (strand, frame, aalen, (start,end) 1-based, len):")
for s,fr,al,(a,b),p in allf:
